/* * @lc app=leetcode id=2122 lang=kotlin * * [2122] Recover the Original Array */ class Solution { fun recoverArray(nums: IntArray): IntArray = nums.sortedArray().let { sorted -> sorted.indices.drop(1).filter { i -> sorted[i] > sorted[0] && (sorted[i] - sorted[0]) % 2 == 0 }.map { i -> (sorted[i] - sorted[0]) / 2 }.firstNotNullOf { k -> BooleanArray(sorted.size).let { used -> IntArray(sorted.size / 2).let { res -> intArrayOf(0, 0).let { state -> if (sorted.indices.all { left -> if (used[left]) true else state.set(1, maxOf(state[1], left + 1)).run { kotlin.DeepRecursiveFunction<Int, Unit> { l -> if (state[1] < sorted.size && (used[state[1]] || sorted[state[1]] < sorted[l] + 2 * k)) state.set(1, state[1] + 1).also { callRecursive(l) } else Unit }.invoke(left) }.run { if (state[1] < sorted.size && sorted[state[1]] == sorted[left] + 2 * k) used.set(left, true).also { used.set(state[1], true) }.also { res.set(state[0].also { state[0]++ }, sorted[left] + k) }.also { state.set(1, state[1] + 1) }.let { true } else false } }) res else null } } } } } }